-- Sales Pipeline dataset (generated by scripts/build_datasets.py; do not edit by hand)
DROP TABLE IF EXISTS sales_targets CASCADE;
DROP TABLE IF EXISTS order_items CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
DROP TABLE IF EXISTS sales_reps CASCADE;
DROP TABLE IF EXISTS regions CASCADE;

CREATE TABLE regions (
  region_id INTEGER PRIMARY KEY,
  region_name VARCHAR(40) NOT NULL UNIQUE
);

CREATE TABLE sales_reps (
  rep_id INTEGER PRIMARY KEY,
  first_name VARCHAR(40) NOT NULL,
  last_name VARCHAR(40) NOT NULL,
  region_id INTEGER NOT NULL REFERENCES regions(region_id),
  hire_date DATE NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  company_name VARCHAR(80) NOT NULL,
  contact_email VARCHAR(120),
  industry VARCHAR(40),
  region_id INTEGER NOT NULL REFERENCES regions(region_id),
  rep_id INTEGER REFERENCES sales_reps(rep_id),
  created_at DATE NOT NULL
);

CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  product_name VARCHAR(80) NOT NULL,
  category VARCHAR(40) NOT NULL,
  unit_price NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0),
  is_discontinued BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE orders (
  order_id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id),
  rep_id INTEGER REFERENCES sales_reps(rep_id),
  order_date DATE NOT NULL,
  ship_date DATE,
  status VARCHAR(12) NOT NULL CHECK (status IN ('pending','shipped','delivered','cancelled','returned')),
  CHECK (ship_date IS NULL OR ship_date >= order_date)
);

CREATE TABLE order_items (
  order_id INTEGER NOT NULL REFERENCES orders(order_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  unit_price NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0),
  discount NUMERIC(4,2) NOT NULL DEFAULT 0 CHECK (discount BETWEEN 0 AND 0.5),
  PRIMARY KEY (order_id, product_id)
);

CREATE TABLE sales_targets (
  rep_id INTEGER NOT NULL REFERENCES sales_reps(rep_id),
  year INTEGER NOT NULL CHECK (year BETWEEN 2020 AND 2030),
  quarter SMALLINT NOT NULL CHECK (quarter BETWEEN 1 AND 4),
  target_amount NUMERIC(12,2) NOT NULL CHECK (target_amount > 0),
  PRIMARY KEY (rep_id, year, quarter)
);

















